'use client';

import React, { useState, useCallback, useSyncExternalStore } from 'react';
import Link from 'next/link';
import { Smartphone, ArrowRight, X } from 'lucide-react';
import { useVerificationStatus } from '@/hooks/useVerificationStatus';

export interface MobileVerificationBannerProps {
  className?: string;
  isModalOpen?: boolean;
}

const BANNER_SNOOZE_KEY = 'trayago_verify_banner_snoozed_until';
const BANNER_SNOOZE_DURATION_MS = 7 * 24 * 60 * 60 * 1000; // 7 days

const emptySubscribe = () => () => {};

export default function MobileVerificationBanner({
  className = '',
  isModalOpen = false
}: MobileVerificationBannerProps) {
  const { isEligibleForReminder, isMobileVerified, isAuthenticated, loading } = useVerificationStatus();
  const [manuallyDismissed, setManuallyDismissed] = useState<boolean>(false);

  // Read client mount state via useSyncExternalStore (SSR-safe, zero cascading renders)
  const isClient = useSyncExternalStore(
    emptySubscribe,
    () => true,
    () => false
  );

  // Read 7-day dismissal window via useSyncExternalStore
  const isSnoozed = useSyncExternalStore(
    emptySubscribe,
    () => {
      try {
        const snoozedUntilStr = localStorage.getItem(BANNER_SNOOZE_KEY);
        if (snoozedUntilStr) {
          const snoozedUntil = parseInt(snoozedUntilStr, 10);
          return Date.now() < snoozedUntil;
        }
      } catch {
        return false;
      }
      return false;
    },
    () => true // start true on server to prevent hydration flicker
  );

  const handleDismiss = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    try {
      const snoozeUntil = Date.now() + BANNER_SNOOZE_DURATION_MS;
      localStorage.setItem(BANNER_SNOOZE_KEY, String(snoozeUntil));
    } catch {}
    setManuallyDismissed(true);
  }, []);

  // Suppress rendering if:
  // 1. Not client-mounted yet (SSR safety)
  // 2. Loading status
  // 3. User is not authenticated or already mobile verified
  // 4. User is not an existing user eligible for reminders (e.g. guest or new gated user)
  // 5. Banner is currently snoozed / dismissed by user
  // 6. The 2-second reminder modal is currently open on screen (avoid visual clutter)
  if (!isClient || loading || !isAuthenticated || isMobileVerified || !isEligibleForReminder || isSnoozed || manuallyDismissed || isModalOpen) {
    return null;
  }

  return (
    <div
      role="region"
      aria-label="Account mobile verification notice"
      className={`relative w-full overflow-hidden rounded-2xl bg-gradient-to-r from-blue-500/10 via-primary/10 to-indigo-500/10 border border-primary/20 dark:border-primary/25 p-3 sm:p-3.5 shadow-xs transition-all duration-200 animate-in fade-in slide-in-from-top-1 ${className}`}
    >
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2.5 sm:gap-4">
        {/* Left Side: Icon & Copy */}
        <div className="flex items-start sm:items-center gap-2.5 min-w-0 flex-1">
          <div className="p-1.5 rounded-xl bg-primary/15 text-primary shrink-0 mt-0.5 sm:mt-0">
            <Smartphone className="w-4 h-4 text-primary" aria-hidden="true" />
          </div>
          <div className="min-w-0 flex-1">
            <p className="text-xs sm:text-xs leading-relaxed text-secondary">
              <strong className="text-main font-bold">Enable Live WhatsApp Alerts: </strong>
              <span className="hidden sm:inline">
                Verify your mobile number to receive live train delay updates, PNR tracking notices, and secure IRCTC booking readiness.
              </span>
              <span className="inline sm:hidden">
                Verify mobile for live train delay &amp; PNR status updates.
              </span>
            </p>
          </div>
        </div>

        {/* Right Side: Action Button & Dismiss X */}
        <div className="flex items-center justify-between sm:justify-end gap-2 shrink-0 pt-1 sm:pt-0 border-t border-subtle/40 sm:border-0">
          <Link
            href="/profile?action=verify-mobile"
            className="inline-flex items-center justify-center gap-1.5 px-3.5 py-1.5 rounded-xl bg-primary hover:brightness-110 active:scale-95 text-white font-bold text-xs shadow-xs transition-all touch-manipulation focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
            aria-label="Verify mobile number on profile page"
          >
            <span>Verify Mobile</span>
            <ArrowRight className="w-3.5 h-3.5" aria-hidden="true" />
          </Link>

          <button
            onClick={handleDismiss}
            className="p-1.5 rounded-lg text-muted hover:text-main hover:bg-input/60 transition-colors touch-manipulation focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
            aria-label="Dismiss verification banner for 7 days"
            title="Dismiss for 7 days"
          >
            <X className="w-4 h-4" aria-hidden="true" />
          </button>
        </div>
      </div>
    </div>
  );
}
