'use client';

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { Sparkles, X, CheckCircle2, Zap, Tag, ArrowRight, Loader2 } from 'lucide-react';
import { API_BASE } from '@/lib/api';
import { fetchWithAuth } from '@/lib/fetchWithAuth';
import { isPaidOrAdminUser } from '@/lib/rescueEntitlement';
import { useRazorpayCheckout } from '@/lib/payment/useRazorpayCheckout';

export default function PromotionalOfferModal() {
  const [mounted, setMounted] = useState(false);
  const [isOpen, setIsOpen] = useState(false);
  const [offer, setOffer] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [claimed, setClaimed] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const { initiatePayment, isLoading: paymentLoading } = useRazorpayCheckout();

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    const fetchOffer = async () => {
      try {
        // Users who already have a paid plan or are admin should NOT see promotional upgrade modals
        if (isPaidOrAdminUser()) {
          return;
        }

        const res = await fetch(`${API_BASE}/content/popup-offer`);
        if (res.ok) {
          const json = await res.json();
          if (json.success && json.data && json.data.isActive) {
            setOffer(json.data);
            // Check if dismissed previously in this session
            const dismissedCode = sessionStorage.getItem('trayago_offer_dismissed');
            if (dismissedCode !== json.data.couponCode) {
              // Delay slightly so visitor sees page first
              setTimeout(() => {
                if (!isPaidOrAdminUser()) {
                  setIsOpen(true);
                }
              }, 1800);
            }
          }
        }
      } catch {
        // Fallback silently if offline
      }
    };

    fetchOffer();
  }, []);

  const handleDismiss = () => {
    if (offer?.couponCode) {
      sessionStorage.setItem('trayago_offer_dismissed', offer.couponCode);
    }
    setIsOpen(false);
  };

  const handleClaim = async () => {
    setErrorMsg(null);

    const userStr = localStorage.getItem('user');
    const token = localStorage.getItem('accessToken');

    if (!userStr || !token) {
      // If guest, save the code so it auto-applies on login/register
      sessionStorage.setItem('pending_promo_code', offer.couponCode || 'OFFER19');
      window.location.href = `/login?redirect=${encodeURIComponent(window.location.pathname)}&promo=${offer.couponCode || 'OFFER19'}`;
      return;
    }

    // Check if this is a paid promotional offer (e.g. ₹19)
    const rawPrice = String(offer.offerPrice || '').replace(/[^\d.]/g, '');
    const priceNum = parseFloat(rawPrice);

    if (!isNaN(priceNum) && priceNum > 0) {
      const targetPlan = offer.planType || 'safar_pro_30d';
      initiatePayment(
        targetPlan,
        {
          onSuccess: () => {
            setClaimed(true);
            try {
              const userObj = JSON.parse(userStr);
              userObj.planType = targetPlan;
              localStorage.setItem('user', JSON.stringify(userObj));
              window.dispatchEvent(new Event('auth-change'));
              window.dispatchEvent(new Event('storage'));
            } catch {}

            setTimeout(() => {
              setIsOpen(false);
            }, 3500);
          },
          onError: (msg, cancelled) => {
            if (!cancelled) {
              setErrorMsg(msg || 'Payment failed. Please try again.');
            }
          }
        },
        offer.couponCode
      );
      return;
    }

    // Free voucher redemption fallback (₹0)
    setLoading(true);
    try {
      // Redeem code
      const res = await fetchWithAuth(`${API_BASE}/beta/redeem`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({ code: offer.couponCode })
      });

      const json = await res.json();
      if (json.success) {
        setClaimed(true);
        // Update user in localStorage
        try {
          const userObj = JSON.parse(userStr);
          userObj.planType = json.plan || offer.planType || 'safar_pro_30d';
          localStorage.setItem('user', JSON.stringify(userObj));
          window.dispatchEvent(new Event('auth-change'));
          window.dispatchEvent(new Event('storage'));
        } catch {}

        setTimeout(() => {
          setIsOpen(false);
        }, 3500);
      } else {
        setErrorMsg(json.error || 'Failed to claim offer. Code may have reached max uses.');
      }
    } catch {
      setErrorMsg('Network error while activating offer.');
    } finally {
      setLoading(false);
    }
  };

  if (!mounted || !isOpen || !offer) return null;

  return createPortal(
    <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-black/75 backdrop-blur-md overflow-y-auto animate-in fade-in duration-300">
      <div className="relative w-full max-w-md max-h-[90vh] overflow-y-auto my-auto bg-card border border-primary/30 rounded-3xl p-6 md:p-7 shadow-2xl animate-in zoom-in-95 duration-300 text-main">
        {/* Ambient Gradient Orbs */}
        <div className="absolute top-0 right-0 w-48 h-48 bg-primary/15 rounded-full blur-3xl pointer-events-none" />
        <div className="absolute bottom-0 left-0 w-48 h-48 bg-emerald-500/15 rounded-full blur-3xl pointer-events-none" />

        {/* Close Button */}
        <button
          onClick={handleDismiss}
          className="absolute top-4 right-4 p-2 rounded-full bg-surface hover:bg-input text-muted hover:text-main transition-colors z-10"
          aria-label="Close offer"
        >
          <X size={16} />
        </button>

        {claimed ? (
          /* Success / Celebration State */
          <div className="py-8 flex flex-col items-center text-center space-y-4">
            <div className="w-16 h-16 rounded-full bg-emerald-500/20 border border-emerald-500/40 text-emerald-500 flex items-center justify-center animate-bounce">
              <CheckCircle2 size={36} />
            </div>
            <div className="space-y-1">
              <h3 className="text-xl font-black text-main">Offer Activated! 🎉</h3>
              <p className="text-xs text-muted max-w-xs">
                Your account has been upgraded to <strong>{offer.durationDays || 30} Days Pro Access</strong>. Enjoy unlimited AI discoveries and live train tracking!
              </p>
            </div>
            <button
              onClick={() => setIsOpen(false)}
              className="px-6 py-2 bg-primary text-white rounded-xl text-xs font-bold transition shadow"
            >
              Start Exploring
            </button>
          </div>
        ) : (
          /* Main Offer Content */
          <div className="space-y-4 relative">
            {/* Header Badge */}
            <div className="flex items-center gap-2">
              <span className="px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-wider bg-primary/15 text-primary border border-primary/30 flex items-center gap-1">
                <Sparkles size={12} />
                {offer.badgeText || 'SPECIAL OFFER'}
              </span>
              <span className="text-[10px] font-mono text-emerald-500 font-bold bg-emerald-500/10 px-2 py-0.5 rounded-full">
                Instant Activation
              </span>
            </div>

            {/* Headline & Pitch */}
            <div>
              <h3 className="text-xl font-black text-main leading-tight">
                {offer.title || 'Festive Travel Freedom Offer'}
              </h3>
              <p className="text-xs text-muted mt-1 leading-relaxed">
                {offer.subtitle}
              </p>
            </div>

            {/* Pricing Strip */}
            <div className="p-3.5 rounded-2xl bg-gradient-to-r from-emerald-500/15 via-primary/10 to-transparent border border-emerald-500/30 flex items-center justify-between">
              <div>
                <div className="text-[10px] font-bold text-muted uppercase">Festive Special</div>
                <div className="flex items-baseline gap-2 mt-0.5">
                  <span className="text-2xl font-black text-emerald-500 font-mono">{offer.offerPrice || '₹19'}</span>
                  {offer.originalPrice && (
                    <span className="text-xs text-muted line-through font-mono">{offer.originalPrice}</span>
                  )}
                  <span className="text-[11px] font-bold text-main">/ {offer.durationDays || 30} Days</span>
                </div>
              </div>
              <div className="text-right">
                <span className="text-[10px] text-muted block">Promo Code:</span>
                <span className="px-2 py-0.5 rounded-md bg-card border border-indigo-500/40 text-indigo-400 font-mono font-black text-xs">
                  {offer.couponCode || 'OFFER19'}
                </span>
              </div>
            </div>

            {/* Feature Bullets */}
            {Array.isArray(offer.features) && offer.features.length > 0 && (
              <div className="space-y-2 py-1">
                {offer.features.map((feat: string, idx: number) => (
                  <div key={idx} className="flex items-center gap-2 text-xs text-secondary">
                    <CheckCircle2 size={14} className="text-emerald-500 shrink-0" />
                    <span>{feat}</span>
                  </div>
                ))}
              </div>
            )}

            {errorMsg && (
              <div className="p-2.5 rounded-xl bg-rose-500/10 border border-rose-500/20 text-rose-500 text-xs font-semibold text-center">
                {errorMsg}
              </div>
            )}

            {/* Claim CTA Button */}
            <button
              onClick={handleClaim}
              disabled={loading || paymentLoading}
              className="w-full py-3.5 bg-gradient-to-r from-emerald-500 via-primary to-indigo-600 hover:opacity-95 text-white rounded-xl text-xs font-black uppercase tracking-wider shadow-lg shadow-primary/25 transition flex items-center justify-center gap-2 disabled:opacity-50"
            >
              {loading || paymentLoading ? (
                <Loader2 size={16} className="animate-spin" />
              ) : (
                <>
                  <Zap size={14} />
                  <span>{offer.ctaText || 'Claim Offer Now'}</span>
                  <ArrowRight size={14} />
                </>
              )}
            </button>

            <div className="flex items-center justify-between text-[11px] text-muted pt-1">
              <button
                onClick={handleDismiss}
                className="hover:text-main underline transition"
              >
                Maybe Later
              </button>
              <span className="text-[10px]">
                {offer.offerPrice && parseFloat(String(offer.offerPrice).replace(/[^\d.]/g, '')) > 0 
                  ? 'Instant activation via secure Razorpay UPI / Card' 
                  : 'No credit card required for promo pass'}
              </span>
            </div>
          </div>
        )}
      </div>
    </div>,
    document.body
  );
}
