"use client";

import React, { useEffect, useState } from "react";
import { Sparkles, ShieldCheck, LogIn, UserPlus, Lock } from "lucide-react";
import BottomSheet from "./ui/BottomSheet";
import { GoogleAuthButton } from "./GoogleAuthButton";
import { saveReturnUrl } from "@/lib/returnUrl";

interface LoginModalProps {
  isOpen: boolean;
  onClose: () => void;
  contextMessage?: string;
  returnUrl?: string;
}

export function LoginModal({
  isOpen,
  onClose,
  contextMessage = "Please sign in to use AI Split Journey & Seat Rescue",
  returnUrl,
}: LoginModalProps) {
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const currentPath = typeof window !== "undefined"
    ? returnUrl || (window.location.pathname + window.location.search)
    : "/";

  useEffect(() => {
    if (isOpen && currentPath && currentPath !== "/") {
      saveReturnUrl(currentPath);
    }
  }, [isOpen, currentPath]);
  const loginReturnHref = currentPath && currentPath !== "/"
    ? `/login?returnUrl=${encodeURIComponent(currentPath)}`
    : "/login";
  const signupReturnHref = currentPath && currentPath !== "/"
    ? `/signup?returnUrl=${encodeURIComponent(currentPath)}`
    : "/signup";

  const handleNav = (href: string) => {
    saveReturnUrl(currentPath);
    if (typeof window !== "undefined") {
      window.location.href = href;
    }
  };

  if (!mounted) return null;

  return (
    <BottomSheet isOpen={isOpen} onClose={onClose} title="Authentication Required">
      <div className="py-2 px-1 text-center max-w-md mx-auto">
        {/* Visual Badge Header */}
        <div className="relative mx-auto mb-4 w-14 h-14 rounded-2xl bg-gradient-to-tr from-emerald-500/20 via-blue-500/20 to-purple-500/20 border border-emerald-500/30 flex items-center justify-center shadow-lg shadow-emerald-500/10">
          <Sparkles className="w-7 h-7 text-emerald-500 dark:text-emerald-400" />
          <div className="absolute -bottom-1 -right-1 w-5 h-5 rounded-full bg-blue-600 text-white flex items-center justify-center shadow-xs">
            <Lock className="w-2.5 h-2.5" />
          </div>
        </div>

        {/* Modal Title */}
        <h3 className="text-xl sm:text-2xl font-black text-main tracking-tight mb-2">
          Sign In to Continue
        </h3>

        {/* Context Alert Message */}
        <div className="mb-5 p-3.5 rounded-2xl bg-emerald-950/60 border border-emerald-500/70 text-emerald-200 text-xs sm:text-sm font-semibold shadow-md shadow-emerald-500/20 text-left flex items-start gap-2.5">
          <ShieldCheck className="w-5 h-5 text-emerald-400 shrink-0 mt-0.5" />
          <div className="space-y-1">
            <p className="font-bold text-white text-xs sm:text-sm">
              {contextMessage}
            </p>
            <p className="text-[11px] text-emerald-300/90 leading-relaxed font-normal">
              Sign in with your Trayago account to unlock AI-powered connecting routes, same-train seat rescue, and personalized ticket assistance.
            </p>
          </div>
        </div>

        {/* Primary Auth CTAs */}
        <div className="space-y-3">
          {/* Google Auth Button */}
          <div className="w-full">
            <GoogleAuthButton
              buttonText="Continue with Google"
              onSuccess={() => {
                onClose();
                if (typeof window !== "undefined") {
                  window.location.reload();
                }
              }}
            />
          </div>

          <div className="relative flex items-center py-1">
            <div className="flex-grow border-t border-subtle" />
            <span className="flex-shrink-0 mx-3 text-muted text-[10px] uppercase tracking-widest font-bold">
              OR
            </span>
            <div className="flex-grow border-t border-subtle" />
          </div>

          {/* Standard Login */}
          <button
            type="button"
            onClick={() => handleNav(loginReturnHref)}
            className="w-full py-3.5 px-4 rounded-xl bg-blue-600 hover:bg-blue-700 active:bg-blue-800 text-white font-bold text-xs sm:text-sm flex items-center justify-center gap-2 shadow-md transition-all active:scale-[0.98] cursor-pointer"
          >
            <LogIn className="w-4 h-4" />
            <span>Sign In with Password / OTP</span>
          </button>

          {/* Create Account */}
          <button
            type="button"
            onClick={() => handleNav(signupReturnHref)}
            className="w-full py-3 px-4 rounded-xl bg-surface hover:bg-input border border-subtle text-main font-bold text-xs sm:text-sm flex items-center justify-center gap-2 transition-all active:scale-[0.98] cursor-pointer"
          >
            <UserPlus className="w-4 h-4 text-muted" />
            <span>Create Free Account</span>
          </button>
        </div>

        {/* Footer Note */}
        <p className="mt-4 text-[10px] text-muted font-medium">
          No IRCTC credentials required for Trayago search. Free accounts get instant access.
        </p>
      </div>
    </BottomSheet>
  );
}

export default LoginModal;

