/**
 * Availability Status Classifier (Phase 8.13)
 * Provides centralized, strict status classification for IRCTC / RailKit railway responses.
 * Guarantees that terminal, unknown, and waitlisted statuses NEVER produce false 100% availability.
 */

export type AvailabilityCategory =
  | 'AVAILABLE'     // Explicit available inventory (AVL, AVAILABLE, CURR_AVBL)
  | 'CONFIRMED'     // Confirmed booked ticket / allocation (CNF, CONFIRMED)
  | 'RAC'           // Reservation Against Cancellation (RAC)
  | 'WAITLISTED'    // Waiting list (GNWL, TQWL, LDWL, SS, RLWL, PQWL, WL)
  | 'TERMINAL'      // Regret / unavailable / departed / cancelled / charting done
  | 'UNKNOWN';      // Empty, missing, or unrecognized status

export interface AvailabilityClassification {
  rawStatus: string;
  normalizedStatus: string;
  category: AvailabilityCategory;
  isAvailable: boolean;     // true ONLY for AVAILABLE
  isConfirmed: boolean;     // true for CONFIRMED or AVAILABLE
  isCurrAvbl: boolean;      // true for current booking
  currSeats: number | null;
  isRac: boolean;           // true ONLY for RAC (never confirmed)
  isWaitlisted: boolean;    // true ONLY for WAITLISTED
  isTerminal: boolean;      // true for terminal / regret
  isUnknown: boolean;       // true for unrecognized / missing
  seatCount: number | null;
  waitlistType: string | null;
  waitlistNumber: number | null;
  racNumber: number | null;
  confidence: number | null; // 100 for AVAILABLE/CONFIRMED, 0 for TERMINAL, null for WL/RAC/UNKNOWN
}

export function classifyAvailability(
  rawInput: unknown,
  isCurrentBookingFlag?: boolean,
  currentBookingSeatsArg?: number | null
): AvailabilityClassification {
  let raw = '';
  if (typeof rawInput === 'string') {
    raw = rawInput.trim();
  } else if (rawInput && typeof rawInput === 'object') {
    const obj = rawInput as Record<string, any>;
    raw = String(obj.status || obj.availabilityText || obj.current_status || '').trim();
  }

  // 1. Missing / Empty Status -> UNKNOWN
  if (!raw) {
    return {
      rawStatus: '',
      normalizedStatus: '',
      category: 'UNKNOWN',
      isAvailable: false,
      isConfirmed: false,
      isCurrAvbl: false,
      currSeats: null,
      isRac: false,
      isWaitlisted: false,
      isTerminal: false,
      isUnknown: true,
      seatCount: null,
      waitlistType: null,
      waitlistNumber: null,
      racNumber: null,
      confidence: null,
    };
  }

  const s = raw.toUpperCase().replace(/\s+/g, ' ').trim();

  // 2. TERMINAL / NON-AVAILABLE / REGRET STATUSES
  // Must be evaluated first to avoid substring false positives (e.g. "NOT AVAILABLE" contains "AVAILABLE")
  const isTerminal =
    s.includes('REGRET') ||
    s.includes('NOT AVAILABLE') ||
    s.includes('CLASS NOT AVAILABLE') ||
    s.includes('NO ROOM') ||
    s.includes('BLOCKED') ||
    s.includes('TRAIN DEPARTED') ||
    s.includes('DEPARTED') ||
    s.includes('CHARTING DONE') ||
    s.includes('CHART PREPARED') ||
    s.includes('CANCELLED') ||
    s.includes('CANCELED') ||
    s.includes('BOOKING CLOSED') ||
    s.includes('UNAVAILABLE');

  if (isTerminal) {
    return {
      rawStatus: raw,
      normalizedStatus: s,
      category: 'TERMINAL',
      isAvailable: false,
      isConfirmed: false,
      isCurrAvbl: false,
      currSeats: null,
      isRac: false,
      isWaitlisted: false,
      isTerminal: true,
      isUnknown: false,
      seatCount: 0,
      waitlistType: null,
      waitlistNumber: null,
      racNumber: null,
      confidence: 0,
    };
  }

  // 3. CURRENT BOOKING (e.g. CURR_AVBL 5, CURR AVBL, CURRENT_AVAILABLE)
  const currMatch = s.match(/CURR(?:ENT)?[\s_-]*AV(?:B|AI)?L(?:ABLE)?[\s_-]*(\d+)?/i);
  const rawSeats = currentBookingSeatsArg !== undefined && currentBookingSeatsArg !== null
    ? currentBookingSeatsArg
    : (currMatch && currMatch[1] ? parseInt(currMatch[1], 10) : null);
  const isCurrAvbl = (isCurrentBookingFlag === true || Boolean(currMatch)) && (rawSeats === null || rawSeats > 0);
  const currSeats = isCurrAvbl ? rawSeats : null;

  if (isCurrAvbl) {
    return {
      rawStatus: raw,
      normalizedStatus: s,
      category: 'AVAILABLE',
      isAvailable: true,
      isConfirmed: true,
      isCurrAvbl: true,
      currSeats,
      isRac: false,
      isWaitlisted: false,
      isTerminal: false,
      isUnknown: false,
      seatCount: currSeats,
      waitlistType: null,
      waitlistNumber: null,
      racNumber: null,
      confidence: 100,
    };
  }

  // 4. EXPLICIT AVAILABLE INVENTORY (e.g. AVL 12, AVAILABLE 4, AVL, AVAILABLE)
  // Strict matching: starts with AVL/AVAILABLE or matches word boundary \b(AVL|AVAILABLE)\b
  const avlMatch = s.match(/(?:AVAILABLE|AVL)[\s_-]*(\d+)?/i);
  const isExplicitAvl = Boolean(
    avlMatch ||
    s.startsWith('AVAILABLE') ||
    s.startsWith('AVL') ||
    s.match(/\bAVAILABLE\b/i) ||
    s.match(/\bAVL\b/i)
  );

  if (isExplicitAvl) {
    const count = avlMatch && avlMatch[1] ? parseInt(avlMatch[1], 10) : null;
    return {
      rawStatus: raw,
      normalizedStatus: s,
      category: 'AVAILABLE',
      isAvailable: true,
      isConfirmed: true,
      isCurrAvbl: false,
      currSeats: null,
      isRac: false,
      isWaitlisted: false,
      isTerminal: false,
      isUnknown: false,
      seatCount: count,
      waitlistType: null,
      waitlistNumber: null,
      racNumber: null,
      confidence: 100,
    };
  }

  // 5. EXPLICIT CONFIRMED BOOKED TICKET STATUS (e.g. CNF, CONFIRMED, CNF / B2 / 34)
  // Must NOT match substring inside arbitrary text (e.g. "NOT CNF" or "CNF/RAC")
  const isExplicitCnf = Boolean(
    s === 'CNF' ||
    s === 'CONFIRMED' ||
    s.startsWith('CNF ') ||
    s.startsWith('CNF/') ||
    s.startsWith('CONFIRMED ')
  );

  if (isExplicitCnf) {
    return {
      rawStatus: raw,
      normalizedStatus: s,
      category: 'CONFIRMED',
      isAvailable: false,
      isConfirmed: true,
      isCurrAvbl: false,
      currSeats: null,
      isRac: false,
      isWaitlisted: false,
      isTerminal: false,
      isUnknown: false,
      seatCount: null,
      waitlistType: null,
      waitlistNumber: null,
      racNumber: null,
      confidence: 100,
    };
  }

  // 6. RAC (RESERVATION AGAINST CANCELLATION) — NEVER CONFIRMED
  const isRac = Boolean(s.match(/\bRAC\b/i) || s.startsWith('RAC'));
  if (isRac) {
    const racMatch = s.match(/RAC[\s_-]*(\d+)?/i) || s.match(/\d+/);
    const racNum = racMatch && racMatch[1] ? parseInt(racMatch[1], 10) : (racMatch && racMatch[0] ? parseInt(racMatch[0], 10) : null);
    return {
      rawStatus: raw,
      normalizedStatus: s,
      category: 'RAC',
      isAvailable: false,
      isConfirmed: false, // RAC IS NEVER CONFIRMED
      isCurrAvbl: false,
      currSeats: null,
      isRac: true,
      isWaitlisted: false,
      isTerminal: false,
      isUnknown: false,
      seatCount: 0,
      waitlistType: 'RAC',
      waitlistNumber: null,
      racNumber: racNum,
      confidence: null, // Preserves ML prediction / prob
    };
  }

  // 7. WAITLIST (GNWL, TQWL, LDWL, SSWL, RLWL, PQWL, RSWL, WL)
  const isWl = Boolean(s.includes('WL') || s.includes('WAITLIST'));
  if (isWl) {
    let wlType = 'WL';
    if (s.includes('PQWL')) wlType = 'PQWL';
    else if (s.includes('RLWL')) wlType = 'RLWL';
    else if (s.includes('GNWL')) wlType = 'GNWL';
    else if (s.includes('TQWL') || s.includes('CKWL')) wlType = 'TQWL';
    else if (s.includes('LDWL')) wlType = 'LDWL';
    else if (s.includes('SSWL') || s.includes('SS')) wlType = 'SSWL';
    else if (s.includes('RSWL')) wlType = 'RSWL';

    const splitMatch = s.match(new RegExp(`${wlType}\\s*(?:\\d+\\s*\\/\\s*WL\\s*)?(\\d+)`, 'i'));
    const anyNumMatch = s.match(/\d+$/) || s.match(/\d+/);
    const wlNum = splitMatch && splitMatch[1] ? parseInt(splitMatch[1], 10) : (anyNumMatch ? parseInt(anyNumMatch[0], 10) : null);

    return {
      rawStatus: raw,
      normalizedStatus: s,
      category: 'WAITLISTED',
      isAvailable: false,
      isConfirmed: false,
      isCurrAvbl: false,
      currSeats: null,
      isRac: false,
      isWaitlisted: true,
      isTerminal: false,
      isUnknown: false,
      seatCount: 0,
      waitlistType: wlType,
      waitlistNumber: wlNum,
      racNumber: null,
      confidence: null, // Preserves ML prediction / prob
    };
  }

  // 8. UNKNOWN / UNRECOGNIZED STATUS — NEVER ASSUME AVAILABLE
  return {
    rawStatus: raw,
    normalizedStatus: s,
    category: 'UNKNOWN',
    isAvailable: false,
    isConfirmed: false,
    isCurrAvbl: false,
    currSeats: null,
    isRac: false,
    isWaitlisted: false,
    isTerminal: false,
    isUnknown: true,
    seatCount: null,
    waitlistType: null,
    waitlistNumber: null,
    racNumber: null,
    confidence: null,
  };
}
